PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?company
WHERE {
  <http://dbpedia.org/resource/Empire_Sports_Network> dbo:owningCompany ?company .
  BIND(?company AS ?owner) .
  OPTIONAL { ?owner dbp:owner ?ownerName }
}
LIMIT 100

